// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event DifficultyChanged(uint256 currentDifficulty);

    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1e30);

        vm.expectEmit(true, true, true, true);
        emit DifficultyChanged(amount);

        // This call triggers AdjustDifficulty which emits the event.
        // In the reference, the emitted value equals 'amount'.
        // In the mutant, it emits 0.
        c.AdjustDifficulty(amount);
    }
}

